#!/usr/bin/env bash
# PreToolUse (Edit|Write|MultiEdit|NotebookEdit): block hand edits to generated files, and to the sibling
# repositories this one reads but never modifies (.claude/CLAUDE.md, "Critical Rules"). Exit 2 blocks the
# tool call and shows the reason to Claude. Tested by scripts/lib/claude-hooks.test.ts.
set -euo pipefail

f=$(jq -r '.tool_input.file_path // .tool_input.notebook_path // empty')
[ -n "$f" ] || exit 0
root="${CLAUDE_PROJECT_DIR:-$PWD}"

block() {
  echo "Blocked: $1" >&2
  exit 2
}

# Sibling repositories: the workspace (../.. : go/, python/, platform-interop-tests …) and the IAM services
# (../../../XPertPMS, the stack's IAM_ROOT default). Read and build them; check pinned commits in scratch clones.
workspace=$(cd "$root/../.." 2>/dev/null && pwd -P || true)
iam=$(cd "$root/../../../XPertPMS" 2>/dev/null && pwd -P || true)
case "$f" in
  "$root"/*) ;;
  "$workspace"/* | "$iam"/*)
    block "$f is in a sibling repository, which this repository only reads and builds. Change it in that repository (its own PR), then move the pin in packages/frontend-sdk/contracts/sources.json." ;;
esac

rel=${f#"$root"/}
case "$rel" in
  packages/frontend-sdk/contracts/sources.json | packages/frontend-sdk/contracts/README.md) ;;
  packages/frontend-sdk/contracts/*.json | packages/frontend-sdk/contracts/fixtures/*)
    block "$rel is generated from the pinned backend commits. Change the source repository (or the pin in contracts/sources.json), then run \`pnpm contracts:sync\`." ;;
  packages/frontend-sdk/src/internal/generated/* | packages/eslint-plugin/src/generated/forbidden-headers.ts)
    block "$rel is generated by scripts/sync-contracts.ts. Run \`pnpm contracts:sync\`." ;;
  packages/*/src/generated/*)
    block "$rel is generated by scripts/sync-exports.ts (the SDK facts). Run \`pnpm exports:sync\`." ;;
  packages/frontend-sdk/api/*.api.md)
    block "$rel is the api-extractor report. Change the subpath's code, then run \`pnpm api\` and review the diff." ;;
  docs/observability/metric-registry.md | docs/observability/tier1-proposal.md | docs/problem-details/registry.md | docs/architecture/mermaid/package-dependencies.mmd)
    block "$rel is generated by scripts/sync-docs.ts. Change its source (the registry, the Tier 1 proposal, problem types or subpaths.json), then run \`pnpm docs:sync\`." ;;
  .env)
    block ".env is the developer's local, untracked config (test/testenv/index.ts reads it). Ask the user to edit it; defaults belong in test/testenv/index.ts." ;;
esac
exit 0
